ldf = ldf[ldf.notna()]
print('mom panel len:', len(ldf))
both = fdf.index.intersection(ldf.index)
print('intersection:', len(both))
if len(both) > 100:
    rho, _ = pearsonr(fdf.loc[both].values, ldf.loc[both].values)
